<script setup lang="ts">
import {ref,computed} from 'vue';import {useStatus} from '../lib/useStatus';import {date} from '../lib/format';import type {Run} from '../types';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import Badge from '../components/Badge.vue';import Modal from '../components/Modal.vue'
const {status,error,loading,load}=useStatus();const filter=ref('all'),selected=ref<Run>();const rows=computed(()=>[...(status.value?.history||[])].reverse().filter(r=>filter.value==='all'||r.status===filter.value))
</script><template><div class="admin-heading"><div><span class="eyebrow">SYNC HISTORY</span><h1>同步记录</h1><p>查看预览计划、实际修改和失败原因。</p></div><button class="btn" :disabled="loading" @click="load"><Icon name="refresh" :size="17"/>刷新记录</button></div><Notice :message="error"/><Notice v-if="status?.pending_operations.length" :message="`有 ${status.pending_operations.length} 条写入尚未核对。只有重新读取到对应 DNS 记录后才会解除，不会自动重发写请求。`"/><section class="card"><div class="card-heading split"><h2>运行历史 <span class="count-label">{{status?.history.length??'—'}}</span></h2><span class="muted">最近 30 轮</span></div><div class="filter-bar"><label class="inline">运行结果<select v-model="filter" aria-label="筛选运行结果"><option value="all">全部结果</option><option value="ok">成功</option><option value="error">失败</option><option value="interrupted">已中断</option></select></label></div><div v-if="rows.length" class="table-scroll"><table><thead><tr><th>运行时间</th><th>模式</th><th>状态</th><th>待更新</th><th>已核验</th><th>操作</th></tr></thead><tbody><tr v-for="(run,index) in rows" :key="index"><td>{{date(run.started_at)}}</td><td><Badge :value="run.mode"/></td><td><Badge :value="run.status"/></td><td>{{run.planned}}</td><td>{{run.changed}}</td><td><button class="btn small" @click="selected=run">查看详情</button></td></tr></tbody></table></div><EmptyState v-else icon="clock" :title="loading?'正在读取记录…':'暂无匹配记录'" text="运行完成后会保留该轮结果。"/></section><Modal :open="!!selected" title="运行详情" @close="selected=undefined"><template v-if="selected"><dl class="detail-list"><div><dt>开始时间</dt><dd>{{date(selected.started_at)}}</dd></div><div><dt>结束时间</dt><dd>{{date(selected.finished_at)}}</dd></div><div><dt>模式</dt><dd><Badge :value="selected.mode"/></dd></div><div><dt>结果</dt><dd><Badge :value="selected.status"/></dd></div></dl><Notice :message="selected.error"/><section v-for="(target,index) in selected.targets" :key="index" class="run-target"><div class="split"><h3>{{target.label}}</h3><Badge :value="target.status"/></div><p class="muted">{{target.name}} · {{target.provider}}</p><Notice :message="target.error"/><div v-for="record in target.records" :key="record.id" class="record-change"><div class="change-values"><code>{{record.current}}</code><Icon name="arrow" :size="16"/><code>{{record.target}}</code></div><Badge :value="record.status"/><p v-if="record.warning" class="help">{{record.warning}}</p></div><p v-if="!target.records.length" class="help">该目标没有可展示的记录计划。</p></section><div v-if="!selected.targets.length" class="notice info">本轮只读取 IP 源，没有配置 DNS 目标。</div><p class="help">预览只生成计划，不修改 DNS。部分成功不会自动回滚。</p></template></Modal></template>
